<script setup lang="ts">
import WorkbenchPage from '../components/WorkbenchPage.vue'
import ResourcePreview from '../components/ResourcePreview.vue'
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Link, VideoPlay } from '@element-plus/icons-vue'
import { api } from '../api/client'
import { friendlyError } from '../utils/presentation'
const items=ref<any[]>([]),loading=ref(true),scopes=ref<any[]>([]),platform=ref(''),scope=ref(''),keyword=ref(''),preview=ref<any>(null),previewOpen=ref(false),brokenCovers=ref<Record<string,boolean>>({})
const tabs=[{key:'',label:'全部'},{key:'bilibili',label:'B站视频'},{key:'douyin',label:'抖音视频'},{key:'article',label:'文章'}]
const allResources=computed(()=>items.value.filter(i=>i.content_type!=='search_entry'))
function category(i:any){return ['bilibili','douyin'].includes(i.platform)?i.platform:'article'}
const counts=computed(()=>Object.fromEntries(tabs.map(t=>[t.key,allResources.value.filter(i=>!t.key||category(i)===t.key).length])))
const rows=computed(()=>allResources.value.filter(i=>(!platform.value||category(i)===platform.value)&&(!scope.value||i.scope===scope.value)&&(!keyword.value.trim()||[i.title_zh,i.title,i.author,...(i.kp_names||[])].join(' ').toLowerCase().includes(keyword.value.trim().toLowerCase()))))
function show(item:any){preview.value=item;previewOpen.value=true}
async function load(){loading.value=true;try{const r:any=await api.get('/resources');items.value=r.items||[];scopes.value=r.scopes||[]}catch(e){ElMessage.error(friendlyError(e,'在线资源加载失败'))}finally{loading.value=false}}
onMounted(load)
</script>
<template>
 <WorkbenchPage class="online-page" label="在线资源列表">
  <template #header><div class="toolbar"><nav class="category-filter" aria-label="平台筛选"><button v-for="tab in tabs" :key="tab.key" :class="{active:platform===tab.key}" :aria-pressed="platform===tab.key" @click="platform=tab.key">{{ tab.label }} <span>{{ counts[tab.key] }}</span></button></nav><div class="toolbar-right"><el-select v-model="scope" clearable placeholder="课程匹配" aria-label="按课程匹配筛选"><el-option v-for="row in scopes" :key="row.value" :value="row.value" :label="row.label" /></el-select><el-input v-model="keyword" clearable placeholder="搜索标题、知识点" aria-label="搜索在线资源" /></div></div></template>
  <div v-loading="loading" class="resource-grid"><article v-for="item in rows" :key="item.resource_id" class="resource-card"><button class="res-cover" :aria-label="`预览 ${item.title_zh||item.title}`" @click="show(item)"><img v-if="item.thumbnail&&!brokenCovers[item.resource_id]" :src="item.thumbnail" :alt="`${item.title_zh||item.title} 封面`" loading="lazy" @error="brokenCovers[item.resource_id]=true" /><span v-else class="cover-fallback"><el-icon><Link v-if="category(item)==='article'" /><VideoPlay v-else /></el-icon><span>{{ item.platform_label }}</span></span></button><div class="res-body"><h3 :title="item.title_zh||item.title">{{ item.title_zh||item.title }}</h3><p class="res-meta">{{ item.platform_label }}<span v-if="item.author&&item.author!==item.platform_label"> · {{ item.author }}</span></p><div class="kp-chips"><span v-for="name in item.kp_names?.slice(0,2)" :key="name">{{ name }}</span></div><footer><span v-if="['restricted','dead','login_required'].includes(item.access_status)" class="access-state">{{ item.access_label }}</span><el-button type="primary" plain @click="show(item)">预览资源</el-button></footer></div></article></div>
  <el-empty v-if="!loading&&!rows.length" description="没有匹配的资源" />
  <ResourcePreview v-model="previewOpen" :resource="preview" />
 </WorkbenchPage>
</template>
<style scoped>
.online-page{max-width:1280px;margin:0 auto}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.category-filter{display:flex;gap:6px}.category-filter button{border:1px solid #e1e9f4;border-radius:8px;padding:8px 12px;color:#526b8a;background:white;font:inherit;font-size:14px;cursor:pointer}.category-filter button.active{background:#edf4ff;border-color:#b5ccec;color:#275cbd;font-weight:600}.category-filter button span{color:#7488a4;font-weight:400;margin-left:4px}.toolbar-right{display:flex;gap:10px}.toolbar-right .el-select{width:138px}.toolbar-right .el-input{width:210px}.resource-grid{display:grid;grid-template-columns: repeat(2, minmax(0, 1fr));gap:14px;align-items:stretch}.resource-card{display:grid;grid-template-columns:112px minmax(0,1fr);gap:16px;padding:16px;border:1px solid #dde7f4;border-radius:12px;background:#fff;min-width:0;min-height:178px}.resource-card:hover{border-color:#a7c2e9}.res-cover{display:flex;align-items:center;justify-content:center;width:112px;height:82px;border:1px solid #dbe8f8;border-radius:8px;background:#eef5ff;color:#547fb5;overflow:hidden;cursor:pointer}.res-cover img{width:100%;height:100%;object-fit:cover}.cover-fallback{display:grid;justify-items:center;gap:6px;font-size:14px}.cover-fallback .el-icon{font-size:25px}.res-body{display:flex;flex-direction:column;gap:8px;min-width:0}.res-body h3{margin:0;min-height:46px;font-size:16px;line-height:1.45;font-weight:600;color:#243e5e;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.res-meta{font-size:14px;margin:0;color:#748398;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.kp-chips{display:flex;gap:6px;white-space:nowrap;overflow:hidden}.kp-chips span{font-size:14px;color:#4c6b93;background:#f1f6fd;padding:3px 7px;border-radius:5px;overflow:hidden;text-overflow:ellipsis}.res-body footer{display:flex;align-items:center;justify-content:flex-end;gap:8px;margin-top:auto}.res-body .el-button{padding:8px 13px;height:32px}.access-state{font-size:14px;color:#a27435;margin-right:auto}@media(max-width:1050px){.resource-grid{grid-template-columns:1fr}}@media(max-width:700px){.toolbar-right{width:100%}.toolbar-right .el-input{flex:1}.resource-card{grid-template-columns:84px minmax(0,1fr);gap:12px}.res-cover{width:84px;height:68px}}
</style>
